/** Prusa option key -> its PrusaSlicer type. */
export const OPTION_TYPES: ReadonlyMap<string, OptionType> = new Map(
  (Object.entries(BY_TYPE) as [OptionType, readonly string[]][]).flatMap(([t, keys]) => keys.map((k) => [k, t])),
);
